#include <stdio.h>
#include "pico/stdlib.h"
#include "hardware/adc.h"
#include "sensor_dsp.h" // Automatically generated by Stride compiler

#define ALERT_LED_PIN 25      // Onboard LED on Raspberry Pi Pico
#define SENSOR_ADC_PIN 26     // GPIO 26 -> ADC 0
#define SENSOR_ADC_CHANNEL 0
#define ADC_MAX_VOLTAGE 3.3f
#define CONVERSION_FACTOR (ADC_MAX_VOLTAGE / (1 << 12))

int main() {
    stdio_init_all();

    // 1. Initialize GPIO for Alert LED
    gpio_init(ALERT_LED_PIN);
    gpio_set_dir(ALERT_LED_PIN, GPIO_OUT);
    gpio_put(ALERT_LED_PIN, 0);

    // 2. Initialize ADC for analog sensor acquisition
    adc_init();
    adc_gpio_init(SENSOR_ADC_PIN);
    adc_select_input(SENSOR_ADC_CHANNEL);

    // 3. Initialize Stride DSP domain state (resets persistent filter history)
    SensorDSP_init();

    // 4. Stride domain I/O signal storage
    double rawSensorVoltage = 0.0;
    double alertThreshold = 2.1; // Voltage threshold for event trigger (2.1V)
    double filteredVoltage = 0.0;
    bool alertTriggered = false;

    printf("===========================================\n");
    printf(" Raspberry Pi Pico - Stride Sensor DSP Monitor\n");
    printf("===========================================\n");

    while (true) {
        // Read analog voltage from sensor
        uint16_t raw_adc = adc_read();
        rawSensorVoltage = (double)(raw_adc * CONVERSION_FACTOR);

        // Execute one step of Stride DSP domain
        SensorDSP_process(
            &rawSensorVoltage,
            &alertThreshold,
            &filteredVoltage,
            &alertTriggered
        );

        // Update hardware alert LED
        gpio_put(ALERT_LED_PIN, alertTriggered);

        if (alertTriggered) {
            printf("[EVENT ALERT] Filtered: %.2f V > Threshold: %.2f V (Raw: %.2f V)\n",
                   filteredVoltage, alertThreshold, rawSensorVoltage);
        }

        sleep_ms(10); // 100 Hz sampling loop
    }

    return 0;
}
